import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { createSingleFlight } from './singleflight.mjs';

test('same key shares a pending Promise; different keys and later calls are independent', async () => {
 const calls = [];
 const resolvers = new Map();
 const get = createSingleFlight(key => {
  calls.push(key);
  return new Promise(resolve => resolvers.set(key, resolve));
 });
 const a = get('a');
 const b = get('b');
 assert.strictEqual(get('a'), a);
 assert.notStrictEqual(a, b);
 await Promise.resolve();
 assert.deepEqual(calls, ['a', 'b']);
 resolvers.get('a')('first');
 assert.equal(await a, 'first');
 assert.strictEqual(get('b'), b);
 const retry = get('a');
 assert.notStrictEqual(retry, a);
 await Promise.resolve();
 assert.deepEqual(calls, ['a', 'b', 'a']);
 resolvers.get('a')('second');
 resolvers.get('b')('other');
 assert.deepEqual(await Promise.all([retry, b]), ['second', 'other']);
});

test('rejection reaches every waiter and evicts the failed entry', async () => {
 const failure = new Error('transient');
 let calls = 0;
 let reject;
 const get = createSingleFlight(() => ++calls === 1
  ? new Promise((_, fail) => { reject = fail; })
  : 'recovered');
 const first = get('a');
 const second = get('a');
 assert.strictEqual(first, second);
 const results = Promise.allSettled([first, second]);
 await Promise.resolve();
 reject(failure);
 assert.deepEqual(await results, [
  { status: 'rejected', reason: failure },
  { status: 'rejected', reason: failure },
 ]);
 assert.equal(await get('a'), 'recovered');
 assert.equal(calls, 2);
 // Allow any orphaned rejection to be reported by the test runner.
 await new Promise(resolve => setImmediate(resolve));
});

test('plain values return shared Promises and are not cached after fulfillment', async () => {
 let calls = 0;
 const get = createSingleFlight(() => ++calls);
 const first = get('a');
 assert.ok(first instanceof Promise);
 assert.strictEqual(get('a'), first);
 assert.equal(await first, 1);
 assert.equal(await get('a'), 2);
});

test('synchronous throws become shared rejections and permit retry', async () => {
 const failure = new Error('synchronous');
 let calls = 0;
 const get = createSingleFlight(() => {
  if (++calls === 1) throw failure;
  return 'ok';
 });
 let first;
 assert.doesNotThrow(() => { first = get('a'); });
 assert.ok(first instanceof Promise);
 assert.strictEqual(get('a'), first);
 await assert.rejects(first, error => error === failure);
 assert.equal(await get('a'), 'ok');
 assert.equal(calls, 2);
});

test('unchanged repro succeeds under strict unhandled-rejection handling', () => {
 const result = spawnSync(process.execPath, [
  '--unhandled-rejections=strict',
  new URL('./repro.mjs', import.meta.url).pathname,
 ], { encoding: 'utf8' });
 assert.ifError(result.error);
 assert.equal(result.status, 0, result.stderr);
 assert.equal(result.stdout.trim(), 'ok');
 assert.equal(result.stderr, '');
});

