import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { createSingleFlight } from './singleflight.mjs';

test('pending calls share a Promise; fulfillment removes the entry', async () => {
 let calls = 0;
 let resolve;
 const get = createSingleFlight(() => {
  calls++;
  return new Promise(r => { resolve = r; });
 });
 const first = get('a');
 assert.ok(first instanceof Promise);
 assert.strictEqual(get('a'), first);
 await Promise.resolve();
 assert.equal(calls, 1);
 resolve('first');
 assert.equal(await first, 'first');
 const retry = get('a');
 assert.notStrictEqual(retry, first);
 await Promise.resolve();
 assert.equal(calls, 2);
 resolve('second');
 assert.equal(await retry, 'second');
});

test('different keys are independent even while one remains pending', async () => {
 const resolvers = new Map();
 const calls = [];
 const get = createSingleFlight(key => {
  calls.push(key);
  return new Promise(resolve => resolvers.set(key, resolve));
 });
 const a = get('a');
 const b = get('b');
 assert.notStrictEqual(a, b);
 await Promise.resolve();
 assert.deepEqual(calls, ['a', 'b']);
 resolvers.get('b')('B');
 assert.equal(await b, 'B');
 assert.strictEqual(get('a'), a);
 resolvers.get('a')('A');
 assert.equal(await a, 'A');
});

test('rejection reaches every waiter and permits an immediate retry', async () => {
 const error = new Error('transient');
 let calls = 0;
 let reject;
 const get = createSingleFlight(() => ++calls === 1
  ? new Promise((_, r) => { reject = r; }) : 'recovered');
 const first = get('a');
 const second = get('a');
 assert.strictEqual(first, second);
 const results = Promise.allSettled([first, second]);
 await Promise.resolve();
 reject(error);
 assert.deepEqual(await results, [
  { status: 'rejected', reason: error },
  { status: 'rejected', reason: error },
 ]);
 assert.equal(await get('a'), 'recovered');
 assert.equal(calls, 2);
});

test('plain values and synchronous throws always produce Promises', async () => {
 const error = new Error('synchronous');
 let calls = 0;
 const get = createSingleFlight(() => {
  if (++calls === 1) throw error;
  return 42;
 });
 let first;
 assert.doesNotThrow(() => { first = get('a'); });
 assert.ok(first instanceof Promise);
 assert.strictEqual(get('a'), first);
 await assert.rejects(first, err => err === error);
 const next = get('a');
 assert.ok(next instanceof Promise);
 assert.equal(await next, 42);
 assert.equal(await get('a'), 42);
 assert.equal(calls, 3);
});

test('handled loader rejection creates no additional unhandled rejection', () => {
 // Strict mode in an isolated process catches orphaned cleanup Promises,
 // independently of the test runner's unhandled-rejection listeners.
 const moduleURL = new URL('./singleflight.mjs', import.meta.url).href;
 const result = spawnSync(process.execPath, [
  '--unhandled-rejections=strict', '--input-type=module', '--eval', `
   import { createSingleFlight } from ${JSON.stringify(moduleURL)};
   const get = createSingleFlight(() => Promise.reject(new Error('expected')));
   await Promise.allSettled([get('a'), get('a')]);
   await new Promise(resolve => setImmediate(resolve));
  `,
 ], { encoding: 'utf8' });
 assert.ifError(result.error);
 assert.equal(result.status, 0, result.stderr);
 assert.equal(result.stderr, '');
});

