import assert from 'node:assert/strict';
import test from 'node:test';
import { createSingleFlight } from './singleflight.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

test('shares an in-flight promise per key, but not across keys', async () => {
  const requests = new Map();
  const calls = [];
  const get = createSingleFlight((key) => {
    calls.push(key);
    const request = deferred();
    requests.set(key, request);
    return request.promise;
  });

  const firstA = get('a');
  const secondA = get('a');
  const firstB = get('b');
  assert.strictEqual(firstA, secondA);
  assert.notStrictEqual(firstA, firstB);
  assert.deepEqual(calls, ['a', 'b']);

  requests.get('a').resolve('A');
  requests.get('b').resolve('B');
  assert.deepEqual(await Promise.all([firstA, secondA, firstB]), ['A', 'A', 'B']);

  const nextA = get('a');
  assert.notStrictEqual(nextA, firstA);
  assert.deepEqual(calls, ['a', 'b', 'a']);
  requests.get('a').resolve('A again');
  assert.equal(await nextA, 'A again');
});

test('a rejection reaches every waiter, then a later call retries', async () => {
  const requests = [];
  const get = createSingleFlight(() => {
    const request = deferred();
    requests.push(request);
    return request.promise;
  });

  const first = get('a');
  const second = get('a');
  assert.strictEqual(first, second);
  assert.equal(requests.length, 1);

  const error = new Error('transient');
  const firstResult = assert.rejects(first, (caught) => caught === error);
  const secondResult = assert.rejects(second, (caught) => caught === error);
  requests[0].reject(error);
  await Promise.all([firstResult, secondResult]);

  const retry = get('a');
  assert.notStrictEqual(retry, first);
  assert.equal(requests.length, 2);
  requests[1].resolve('ok');
  assert.equal(await retry, 'ok');
});

test('plain values are wrapped in promises and are not cached', async () => {
  let calls = 0;
  const get = createSingleFlight(() => ++calls);

  const first = get('a');
  assert.ok(first instanceof Promise);
  assert.strictEqual(get('a'), first);
  assert.equal(await first, 1);
  assert.equal(await get('a'), 2);
  assert.equal(calls, 2);
});

test('a synchronous throw becomes a shared rejection and can be retried', async () => {
  let calls = 0;
  const error = new Error('sync failure');
  const get = createSingleFlight(() => {
    if (++calls === 1) throw error;
    return 'ok';
  });

  let first;
  assert.doesNotThrow(() => {
    first = get('a');
  });
  assert.ok(first instanceof Promise);
  assert.strictEqual(get('a'), first);
  await assert.rejects(first, (caught) => caught === error);
  assert.equal(calls, 1);
  assert.equal(await get('a'), 'ok');
  assert.equal(calls, 2);
});

test('a reentrant request for the same key shares the pending promise', async () => {
  let nested;
  let calls = 0;
  let get;
  get = createSingleFlight((key) => {
    calls++;
    nested = get(key);
    return 'ok';
  });

  const outer = get('a');
  assert.strictEqual(nested, outer);
  assert.equal(await outer, 'ok');
  assert.equal(calls, 1);
});

