export function createSingleFlight(load) {
  const pending = new Map();

  return function get(key) {
    if (pending.has(key)) return pending.get(key);

    // Defer load until after the promise is cached, and turn synchronous
    // returns or throws into promise fulfillment or rejection.
    const p = Promise.resolve().then(() => load(key));
    pending.set(key, p);

    // Handle both outcomes. An ignored finally() (or one-sided then()) would
    // create a second, unhandled rejection when load fails.
    p.then(
      () => pending.delete(key),
      () => pending.delete(key),
    );
    return p;
  };
}

