import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { test } from 'node:test';
import { createSingleFlight } from './singleflight.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((yes, no) => {
    resolve = yes;
    reject = no;
  });
  return { promise, resolve, reject };
}

test('same key shares a pending promise; different keys do not', async () => {
  const requests = new Map();
  const calls = [];
  const get = createSingleFlight((key) => {
    calls.push(key);
    const request = deferred();
    requests.set(key, request);
    return request.promise;
  });

  const first = get('a');
  assert.strictEqual(get('a'), first);
  const other = get('b');
  assert.notStrictEqual(other, first);
  await Promise.resolve(); // Let both loaders start.
  assert.deepEqual(calls, ['a', 'b']);

  requests.get('b').resolve('B');
  assert.equal(await other, 'B');
  requests.get('a').resolve('A');
  assert.equal(await first, 'A');
});

test('a fulfilled entry is removed and the next call loads again', async () => {
  let calls = 0;
  const get = createSingleFlight(() => ++calls); // Plain values are supported.

  const first = get('a');
  assert.ok(first instanceof Promise);
  assert.strictEqual(get('a'), first);
  assert.equal(await first, 1);
  assert.equal(await get('a'), 2);
  assert.equal(calls, 2);
});

test('a rejection reaches every waiter and a later call retries', async () => {
  let calls = 0;
  const failure = new Error('transient');
  const request = deferred();
  const get = createSingleFlight(() => ++calls === 1 ? request.promise : 'ok');

  const first = get('a');
  const second = get('a');
  assert.strictEqual(second, first);
  await Promise.resolve();
  assert.equal(calls, 1);
  request.reject(failure);
  await assert.rejects(first, (error) => error === failure);
  await assert.rejects(second, (error) => error === failure);
  assert.equal(await get('a'), 'ok');
  assert.equal(calls, 2);
});

test('a synchronous throw becomes a rejected promise and can be retried', async () => {
  let calls = 0;
  const failure = new Error('sync failure');
  const get = createSingleFlight(() => {
    if (++calls === 1) throw failure;
    return 'ok';
  });

  const first = get('a');
  assert.ok(first instanceof Promise);
  await assert.rejects(first, (error) => error === failure);
  assert.equal(await get('a'), 'ok');
  assert.equal(calls, 2);
});

test('handled load rejection does not create another unhandled rejection', () => {
  const script = `
    import { createSingleFlight } from './singleflight.mjs';
    const get = createSingleFlight(() => Promise.reject(new Error('expected')));
    try { await get('a'); } catch (error) {
      if (error.message !== 'expected') process.exitCode = 1;
    }
    await new Promise((resolve) => setTimeout(resolve, 0));
  `;
  const result = spawnSync(process.execPath, [
    '--unhandled-rejections=strict', '--input-type=module', '-e', script,
  ], { cwd: import.meta.dirname, encoding: 'utf8' });
  assert.equal(result.status, 0, result.stderr);
});

