export function createSingleFlight(load) {
 const pending = new Map();
 return function get(key) {
  if (pending.has(key)) return pending.get(key);
  // Defer load into a promise callback so synchronous throws become rejections
  // and the in-flight promise is installed before load can run.
  const p = Promise.resolve().then(() => load(key));
  pending.set(key, p);
  // Supply both handlers: using finally (or a fulfillment-only then) would
  // create a second rejected promise that may be left unhandled.
  const remove = () => {
   if (pending.get(key) === p) pending.delete(key);
  };
  p.then(remove, remove);
  return p;
 };
}

