import test from 'node:test';
import assert from 'node:assert/strict';
import { createSingleFlight } from './singleflight.mjs';

test('shares pending work for the same key, but not different keys', async () => {
  const releases = new Map();
  const calls = [];
  const get = createSingleFlight((key) => {
    calls.push(key);
    return new Promise((resolve) => releases.set(key, resolve));
  });

  const a1 = get('a');
  const a2 = get('a');
  const b = get('b');
  assert.equal(a1, a2);
  assert.notEqual(a1, b);
  await Promise.resolve();
  assert.deepEqual(calls, ['a', 'b']);
  releases.get('a')('A');
  releases.get('b')('B');
  assert.deepEqual(await Promise.all([a1, a2, b]), ['A', 'A', 'B']);
});

test('removes fulfilled entries so a later call reloads', async () => {
  let calls = 0;
  const get = createSingleFlight(() => ++calls);
  assert.equal(await get('x'), 1);
  assert.equal(await get('x'), 2);
  assert.equal(calls, 2);
});

test('removes rejected entries, shares rejection, and does not create an unhandled rejection', async () => {
  let calls = 0;
  const failure = new Error('transient');
  const unhandled = [];
  const onUnhandled = (reason) => unhandled.push(reason);
  process.on('unhandledRejection', onUnhandled);
  try {
    const get = createSingleFlight(() => {
      if (++calls === 1) throw failure;
      return 'recovered';
    });
    const first = get('x');
    const second = get('x');
    assert.equal(first, second);
    assert.ok(first instanceof Promise);
    const settled = await Promise.allSettled([first, second]);
    assert.deepEqual(settled, [
      { status: 'rejected', reason: failure },
      { status: 'rejected', reason: failure },
    ]);
    assert.equal(await get('x'), 'recovered');
    assert.equal(calls, 2);
    // Give Node's unhandled-rejection reporting turn an opportunity to run.
    await new Promise((resolve) => setImmediate(resolve));
    assert.deepEqual(unhandled, []);
  } finally {
    process.off('unhandledRejection', onUnhandled);
  }
});

test('a synchronous throw always becomes a shared rejected Promise', async () => {
  const error = new Error('sync failure');
  const get = createSingleFlight(() => { throw error; });
  const first = get('x');
  const second = get('x');
  assert.ok(first instanceof Promise);
  assert.equal(first, second);
  await assert.rejects(first, (actual) => actual === error);
});

