export function createSingleFlight(load) {
  const pending = new Map();

  return function get(key) {
    if (pending.has(key)) return pending.get(key);

    // Defer load to a microtask so synchronous throws become rejections and
    // the promise is in the map before load starts.
    const promise = Promise.resolve().then(() => load(key));
    pending.set(key, promise);

    // Handle both outcomes without creating an ignored rejected promise (as
    // `finally` would when `promise` rejects).
    const cleanup = () => {
      if (pending.get(key) === promise) pending.delete(key);
    };
    promise.then(cleanup, cleanup);

    return promise;
  };
}

