import assert from 'node:assert/strict';
import test from 'node:test';
import { createSingleFlight } from './singleflight.mjs';

test('same-key calls share a pending promise; fulfilled entries are retried', async () => {
  let calls = 0;
  let resolveFirst;
  const get = createSingleFlight(() => {
    calls += 1;
    if (calls === 1) return new Promise((resolve) => { resolveFirst = resolve; });
    return 'second result';
  });

  const first = get('key');
  const joined = get('key');
  assert.equal(first instanceof Promise, true);
  assert.strictEqual(joined, first);
  assert.equal(calls, 0); // load starts in a microtask, after registration

  await Promise.resolve();
  assert.equal(calls, 1);
  resolveFirst('first result');
  assert.deepEqual(await Promise.all([first, joined]), ['first result', 'first result']);

  assert.equal(await get('key'), 'second result');
  assert.equal(calls, 2);
});

test('rejection is shared by waiters and a later call retries', async () => {
  let calls = 0;
  const get = createSingleFlight(() => {
    calls += 1;
    if (calls === 1) throw new Error('transient failure');
    return 'recovered';
  });

  const first = get('key');
  const joined = get('key');
  assert.strictEqual(joined, first);
  assert.equal(first instanceof Promise, true);
  await Promise.all([
    assert.rejects(first, /transient failure/),
    assert.rejects(joined, /transient failure/),
  ]);

  assert.equal(await get('key'), 'recovered');
  assert.equal(calls, 2);
});

test('plain values are promised and different keys run independently', async () => {
  const started = [];
  const get = createSingleFlight((key) => {
    started.push(key);
    return key.toUpperCase();
  });

  const a = get('a');
  const b = get('b');
  assert.notStrictEqual(a, b);
  assert.deepEqual(await Promise.all([a, b]), ['A', 'B']);
  assert.deepEqual(started, ['a', 'b']);
});

