export function createSingleFlight(load) {
  const pending = new Map();

  return function get(key) {
    if (pending.has(key)) return pending.get(key);

    // Invoke load in a promise callback so even a synchronous throw becomes a
    // rejection, and so the promise can be registered before load starts.
    const promise = Promise.resolve().then(() => load(key));
    pending.set(key, promise);

    const clear = () => {
      // Guard against deleting a newer request if this implementation is ever
      // extended to replace in-flight entries.
      if (pending.get(key) === promise) pending.delete(key);
    };

    // Supplying both handlers makes the cleanup branch itself fulfill. Using
    // finally(), or then() with only a fulfillment handler, would create an
    // ignored child promise that rejects when the load rejects.
    promise.then(clear, clear);

    return promise;
  };
}

