import assert from 'node:assert/strict';
import test from 'node:test';

import { createSingleFlight } from './singleflight.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

test('same-key callers share one pending promise and success is not cached', async () => {
  const firstLoad = deferred();
  let calls = 0;
  const get = createSingleFlight(() => {
    calls += 1;
    return calls === 1 ? firstLoad.promise : 'fresh';
  });

  const first = get('a');
  const second = get('a');

  assert.strictEqual(second, first);
  await Promise.resolve();
  assert.equal(calls, 1);

  firstLoad.resolve('initial');
  assert.deepEqual(await Promise.all([first, second]), ['initial', 'initial']);

  const third = get('a');
  assert.notStrictEqual(third, first);
  assert.equal(await third, 'fresh');
  assert.equal(calls, 2);
});

test('different keys have independent in-flight requests', async () => {
  const loads = new Map();
  const calls = [];
  const get = createSingleFlight((key) => {
    calls.push(key);
    const load = deferred();
    loads.set(key, load);
    return load.promise;
  });

  const a = get('a');
  const b = get('b');
  assert.notStrictEqual(a, b);

  await Promise.resolve();
  assert.deepEqual(calls, ['a', 'b']);

  loads.get('b').resolve('B');
  assert.equal(await b, 'B');

  let aSettled = false;
  a.then(() => {
    aSettled = true;
  });
  await Promise.resolve();
  assert.equal(aSettled, false);

  loads.get('a').resolve('A');
  assert.equal(await a, 'A');
});

test('rejected loads reject every waiter, are cleaned up, and do not leak a rejection', async () => {
  const unhandled = [];
  const onUnhandled = (reason) => unhandled.push(reason);
  process.on('unhandledRejection', onUnhandled);

  try {
    const firstLoad = deferred();
    let calls = 0;
    const failure = new Error('transient');
    const get = createSingleFlight(() => {
      calls += 1;
      return calls === 1 ? firstLoad.promise : 'ok';
    });

    const first = get('a');
    const second = get('a');
    assert.strictEqual(second, first);
    await Promise.resolve();
    firstLoad.reject(failure);

    const results = await Promise.allSettled([first, second]);
    assert.deepEqual(
      results.map(({ status, reason }) => ({ status, reason })),
      [
        { status: 'rejected', reason: failure },
        { status: 'rejected', reason: failure },
      ],
    );

    assert.equal(await get('a'), 'ok');
    assert.equal(calls, 2);

    // Let Node perform its unhandled-rejection bookkeeping. The internal
    // cleanup continuation must not have produced an unobserved rejected child.
    await new Promise((resolve) => setImmediate(resolve));
    assert.deepEqual(unhandled, []);
  } finally {
    process.off('unhandledRejection', onUnhandled);
  }
});

test('a synchronous load throw is returned as a promise rejection', async () => {
  const failure = new Error('synchronous failure');
  let calls = 0;
  const get = createSingleFlight(() => {
    calls += 1;
    if (calls === 1) throw failure;
    return 'recovered';
  });

  let result;
  assert.doesNotThrow(() => {
    result = get('a');
  });
  assert.ok(result instanceof Promise);
  await assert.rejects(result, (error) => error === failure);
  assert.equal(await get('a'), 'recovered');
  assert.equal(calls, 2);
});

test('a plain load value is exposed as a promise', async () => {
  const get = createSingleFlight((key) => key.toUpperCase());
  const result = get('value');

  assert.ok(result instanceof Promise);
  assert.equal(await result, 'VALUE');
});

