export function createSingleFlight(load) {
  const pending = new Map();

  return function get(key) {
    if (pending.has(key)) return pending.get(key);

    // Start load in a promise callback so synchronous throws become rejections.
    const loadPromise = Promise.resolve().then(() => load(key));
    const sharedPromise = loadPromise.finally(() => {
      // Do not let an older request remove a newer entry for the same key.
      if (pending.get(key) === sharedPromise) pending.delete(key);
    });

    pending.set(key, sharedPromise);
    return sharedPromise;
  };
}

