import assert from 'node:assert/strict';
import test from 'node:test';

import { createSingleFlight } from './singleflight.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

test('concurrent calls for one key share a promise and successful entries expire', async () => {
  const first = deferred();
  let calls = 0;
  const get = createSingleFlight(() => {
    calls += 1;
    return calls === 1 ? first.promise : 'fresh';
  });

  const a = get('same');
  const b = get('same');
  assert.strictEqual(a, b);
  assert.equal(calls, 0, 'load starts asynchronously');

  await Promise.resolve();
  assert.equal(calls, 1);
  first.resolve('first');
  assert.deepEqual(await Promise.all([a, b]), ['first', 'first']);

  assert.equal(await get('same'), 'fresh');
  assert.equal(calls, 2);
});

test('different keys have independent in-flight requests', async () => {
  const requests = new Map();
  const calls = [];
  const get = createSingleFlight((key) => {
    calls.push(key);
    const request = deferred();
    requests.set(key, request);
    return request.promise;
  });

  const a = get('a');
  const b = get('b');
  assert.notStrictEqual(a, b);
  await Promise.resolve();
  assert.deepEqual(calls, ['a', 'b']);

  requests.get('b').resolve('B');
  requests.get('a').resolve('A');
  assert.deepEqual(await Promise.all([a, b]), ['A', 'B']);
});

test('a rejection reaches every waiter, is cleaned up, and does not create an extra rejection', async () => {
  const transient = new Error('transient');
  const first = deferred();
  let calls = 0;
  const get = createSingleFlight(() => {
    calls += 1;
    return calls === 1 ? first.promise : 'recovered';
  });

  const unhandled = [];
  const onUnhandled = (reason) => unhandled.push(reason);
  process.on('unhandledRejection', onUnhandled);
  try {
    const a = get('key');
    const b = get('key');
    assert.strictEqual(a, b);
    await Promise.resolve();
    first.reject(transient);

    const results = await Promise.allSettled([a, b]);
    assert.deepEqual(results, [
      { status: 'rejected', reason: transient },
      { status: 'rejected', reason: transient },
    ]);

    assert.equal(await get('key'), 'recovered');
    assert.equal(calls, 2);
    await new Promise((resolve) => setImmediate(resolve));
    assert.deepEqual(unhandled, []);
  } finally {
    process.off('unhandledRejection', onUnhandled);
  }
});

test('a synchronous throw is returned as a rejected promise and can be retried', async () => {
  const failure = new Error('sync failure');
  let calls = 0;
  const get = createSingleFlight(() => {
    calls += 1;
    if (calls === 1) throw failure;
    return 42;
  });

  let result;
  assert.doesNotThrow(() => {
    result = get('key');
  });
  assert.ok(result instanceof Promise);
  await assert.rejects(result, (error) => error === failure);

  assert.equal(await get('key'), 42);
  assert.equal(calls, 2);
});

