import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { reconcile } from './reconcile.mjs';

const set = (id, account, version, amount) => ({ id, account, version, op: 'set', amount });
const del = (id, account, version) => ({ id, account, version, op: 'delete' });
const row = (account, balance, version) => ({ account, balance, version });
const result = (accounts = [], total = 0, duplicates = 0, stale = 0) =>
  ({ accounts, total, duplicates, stale });

test('empty input', () => {
  assert.deepEqual(reconcile([]), result());
});

test('fixture preserves winners, tombstones, and all counters', () => {
  const events = JSON.parse(readFileSync(new URL('./events.json', import.meta.url), 'utf8'));
  assert.deepEqual(reconcile(events), result([row('b', 40, 3), row('c', 0, 0)], 40, 1, 5));
});

test('deduplicates globally before choosing account winners', () => {
  assert.deepEqual(reconcile([
    set('same', 'a', 1, 4), set('same', 'b', 9, 99),
    del('same', 'a', 10), set('other', 'b', 0, 2),
  ]), result([row('a', 4, 1), row('b', 2, 0)], 6, 2));
});

test('IDs of stale events are still globally reserved', () => {
  assert.deepEqual(reconcile([
    set('winner', 'a', 10, 8), set('old', 'a', 1, 1), set('old', 'b', 20, 9),
  ]), result([row('a', 8, 10)], 8, 1, 1));
});

test('counts both older arrivals and winners superseded later as stale', () => {
  assert.deepEqual(reconcile([
    set('1', 'a', 2, 2), set('2', 'a', 1, 1),
    set('3', 'a', 4, 4), set('4', 'a', 3, 3), set('5', 'a', 5, 5),
  ]), result([row('a', 5, 5)], 5, 0, 4));
});

test('equal versions keep the first distinct event for sets and deletes', () => {
  assert.deepEqual(reconcile([
    set('1', 'a', 3, 7), set('2', 'a', 3, 99), del('3', 'a', 3),
    del('4', 'b', 0), set('5', 'b', 0, 20),
  ]), result([row('a', 7, 3)], 7, 0, 3));
});

test('tombstones defeat older sets and can be superseded by newer sets', () => {
  assert.deepEqual(reconcile([
    del('1', 'a', 5), set('2', 'a', 4, 100),
    set('3', 'b', 1, 2), del('4', 'b', 2), set('5', 'b', 3, 6),
  ]), result([row('b', 6, 3)], 6, 0, 3));
});

test('all-deleted accounts still have winners for stale accounting', () => {
  assert.deepEqual(reconcile([
    del('1', 'a', 0), del('2', 'a', 1), del('3', 'b', 0), del('3', 'b', 0),
  ]), result([], 0, 1, 1));
});

test('sorts accounts in ASCII order, not insertion or locale order', () => {
  const names = ['z', 'a', '_', 'Z', 'A', '10', '2', ''];
  assert.deepEqual(reconcile(names.map((name, i) => set(String(i), name, 0, 1))),
    result(['', '10', '2', 'A', 'Z', '_', 'a', 'z'].map(name => row(name, 1, 0)), 8));
});

test('supports zero, safe-integer boundaries, and special string keys', () => {
  assert.deepEqual(reconcile([
    set('__proto__', '__proto__', Number.MAX_SAFE_INTEGER, 0),
    set('constructor', 'constructor', 0, Number.MAX_SAFE_INTEGER),
    del('', '__proto__', Number.MAX_SAFE_INTEGER - 1),
  ]), result([row('__proto__', 0, Number.MAX_SAFE_INTEGER),
    row('constructor', Number.MAX_SAFE_INTEGER, 0)], Number.MAX_SAFE_INTEGER, 0, 1));
});

test('does not mutate input, returns fresh rows, and keeps no cross-call state', () => {
  const events = Object.freeze([
    Object.freeze(set('1', 'b', 0, 4)), Object.freeze(set('2', 'a', 0, 2)),
  ]);
  const before = JSON.stringify(events);
  const expected = result([row('a', 2, 0), row('b', 4, 0)], 6);
  const actual = reconcile(events);
  assert.deepEqual(actual, expected);
  actual.accounts[0].balance = 999;
  assert.equal(JSON.stringify(events), before);
  assert.deepEqual(reconcile(events), expected);
  assert.deepEqual(reconcile([]), result());
});

