export function reconcile(events) {
  const seen = new Set();
  const winners = new Map();
  let duplicates = 0;
  let distinct = 0;

  for (const event of events) {
    if (seen.has(event.id)) {
      duplicates++;
      continue;
    }
    seen.add(event.id);
    distinct++;

    const winner = winners.get(event.account);
    // Strict comparison preserves the first distinct event on version ties.
    // Keep deletes as winners so older sets cannot resurrect an account.
    if (!winner || event.version > winner.version) {
      winners.set(event.account, event);
    }
  }

  const accounts = [...winners.values()]
    .filter(event => event.op === 'set')
    .map(event => ({
      account: event.account,
      balance: event.amount,
      version: event.version,
    }))
    .sort((a, b) => a.account < b.account ? -1 : a.account > b.account ? 1 : 0);

  return {
    accounts,
    total: accounts.reduce((sum, account) => sum + account.balance, 0),
    duplicates,
    // Every account has exactly one final winner, including deleted accounts.
    stale: distinct - winners.size,
  };
}

