import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { reconcile } from './reconcile.mjs';

const set = (id, account, version, amount = 1) => ({ id, account, version, op: 'set', amount });
const del = (id, account, version) => ({ id, account, version, op: 'delete' });
const row = (account, balance, version) => ({ account, balance, version });
const result = (accounts = [], total = 0, duplicates = 0, stale = 0) =>
  ({ accounts, total, duplicates, stale });
const fixture = JSON.parse(readFileSync(new URL('./events.json', import.meta.url), 'utf8'));
const fixtureExpected = result([row('b', 40, 3), row('c', 0, 0)], 40, 1, 5);

test('empty input', () => {
  assert.deepEqual(reconcile([]), result());
});

test('provided fixture', () => {
  assert.deepEqual(reconcile(fixture), fixtureExpected);
});

test('IDs are deduplicated globally before account/version processing', () => {
  assert.deepEqual(reconcile([
    set('same', 'a', 1, 5), set('same', 'b', 99, 999),
    del('same', 'a', 100), set('new', 'b', 0, 2),
  ]), result([row('a', 5, 1), row('b', 2, 0)], 7, 2, 0));
});

test('IDs remain seen after their original event becomes stale', () => {
  assert.deepEqual(reconcile([
    set('old', 'a', 1), set('new', 'a', 2, 4), set('old', 'z', 99),
  ]), result([row('a', 4, 2)], 4, 1, 1));
});

test('greatest version wins and stale includes later superseded events', () => {
  assert.deepEqual(reconcile([
    set('1', 'a', 1), set('2', 'a', 4, 8),
    set('3', 'a', 2), set('4', 'a', 5, 9),
  ]), result([row('a', 9, 5)], 9, 0, 3));
});

test('version ties retain first distinct event, for sets and deletes', () => {
  assert.deepEqual(reconcile([
    set('1', 'a', 2, 7), set('2', 'a', 2, 99), del('3', 'a', 2),
    del('4', 'b', 3), set('5', 'b', 3), del('6', 'b', 3),
  ]), result([row('a', 7, 2)], 7, 0, 4));
});

test('tombstones defeat older sets, including sets arriving later', () => {
  assert.deepEqual(reconcile([
    set('1', 'a', 1), del('2', 'a', 3), set('3', 'a', 2),
    del('4', 'b', 4), set('5', 'b', 0),
  ]), result([], 0, 0, 3));
});

test('newer sets can replace tombstones and older deletes cannot erase sets', () => {
  assert.deepEqual(reconcile([
    del('1', 'a', 1), set('2', 'a', 3, 6), del('3', 'a', 2),
  ]), result([row('a', 6, 3)], 6, 0, 2));
});

test('ASCII sorting, zero values, safe integer boundary, and special keys', () => {
  const names = ['z', 'a', '_', 'Z', 'A', '10', '2', '__proto__', 'constructor', ''];
  const events = names.map((name, i) => set(String(i), name, 0, 0));
  events.push(set('max', 'max', Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER));
  assert.deepEqual(reconcile(events), result(
    ['', '10', '2', 'A', 'Z', '_', '__proto__', 'a', 'constructor', 'max', 'z']
      .map(name => row(name, name === 'max' ? Number.MAX_SAFE_INTEGER : 0,
        name === 'max' ? Number.MAX_SAFE_INTEGER : 0)),
    Number.MAX_SAFE_INTEGER,
  ));
});

test('does not mutate input or expose input objects through output', () => {
  const input = structuredClone(fixture);
  const before = structuredClone(input);
  input.forEach(Object.freeze);
  Object.freeze(input);
  const output = reconcile(input);
  output.accounts[0].balance = 123;
  assert.deepEqual(input, before);
  assert.deepEqual(reconcile(input), fixtureExpected);
});

test('report equals actual reconciliation of events.json', () => {
  const report = JSON.parse(readFileSync(new URL('./report.json', import.meta.url), 'utf8'));
  assert.deepEqual(report, reconcile(fixture));
});

