export function reconcile(events) {
  const seenIds = new Set();
  const winners = new Map();
  let duplicates = 0;
  let stale = 0;

  for (const event of events) {
    if (seenIds.has(event.id)) {
      duplicates++;
      continue;
    }
    seenIds.add(event.id);

    const previous = winners.get(event.account);
    if (previous !== undefined) {
      // Exactly one distinct event wins per account, even if it is a delete.
      stale++;
    }
    if (previous === undefined || event.version > previous.version) {
      winners.set(event.account, event);
    }
  }

  const accounts = [...winners.entries()]
    .filter(([, event]) => event.op === 'set')
    .map(([account, event]) => ({
      account,
      balance: event.amount,
      version: event.version,
    }))
    .sort((a, b) => (a.account < b.account ? -1 : a.account > b.account ? 1 : 0));

  return {
    accounts,
    total: accounts.reduce((sum, account) => sum + account.balance, 0),
    duplicates,
    stale,
  };
}

