      duplicates += 1;
      continue;
    }
    seenIds.add(event.id);
    distinct += 1;

    const current = winners.get(event.account);
    if (!current || event.version > current.event.version) {
      winners.set(event.account, { event, count: 1 });
    } else {
      current.count += 1;
    }
  }

  const accounts = [];
  let stale = 0;
  for (const { event: winner, count } of winners.values()) {
    stale += count - 1;
    if (winner.op === 'set') {
      accounts.push({ account: winner.account, balance: winner.amount, version: winner.version });
    }
  }
  accounts.sort((a, b) => (a.account < b.account ? -1 : a.account > b.account ? 1 : 0));

  return {
    accounts,
    total: accounts.reduce((sum, account) => sum + account.balance, 0),
    duplicates,
    stale: distinct - winners.size,
  };
}

