export function reconcile(events) {
  const seenIds = new Set();
  const winners = new Map();
  let duplicates = 0;
  let uniqueEvents = 0;

  for (const event of events) {
    // IDs are global: a repeated ID cannot participate in another account.
    if (seenIds.has(event.id)) {
      duplicates += 1;
      continue;
    }

    seenIds.add(event.id);
    uniqueEvents += 1;

    const winner = winners.get(event.account);
    // Deliberately do not replace on equality: input order breaks ties.
    if (winner === undefined || event.version > winner.version) {
      winners.set(event.account, event);
    }
  }

  const accounts = [];
  let total = 0;

  for (const [account, winner] of winners) {
    if (winner.op === 'delete') continue;

    const result = {
      account,
      balance: winner.amount,
      version: winner.version,
    };
    accounts.push(result);
    total += result.balance;
  }

  accounts.sort((left, right) =>
    left.account < right.account ? -1 : left.account > right.account ? 1 : 0,
  );

  return {
    accounts,
    total,
    duplicates,
    stale: uniqueEvents - winners.size,
  };
}

