export function createSingleFlight(load) {
 const pending = new Map();
 return function get(key) {
  if (pending.has(key)) return pending.get(key);
  const p = Promise.resolve().then(() => load(key)).then(
   value => {
    pending.delete(key);
    return value;
   },
   error => {
    pending.delete(key);
    throw error;
   }
  );
  pending.set(key,p);
  return p;
 };
}

