import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import test from 'node:test';
import { createSingleFlight } from './singleflight.mjs';

test('same-key callers share one Promise; fulfillment permits a fresh load', async () => {
 const loads = [];
 const get = createSingleFlight(key => new Promise(resolve => {
  loads.push({ key, resolve });
 }));
 const first = get('a');
 const second = get('a');
 assert.ok(first instanceof Promise);
 assert.strictEqual(first, second);
 await Promise.resolve();
 assert.equal(loads.length, 1);
 assert.equal(loads[0].key, 'a');
 loads[0].resolve('first');
 assert.deepEqual(await Promise.all([first, second]), ['first', 'first']);

 const retry = get('a');
 assert.notStrictEqual(retry, first);
 await Promise.resolve();
 assert.equal(loads.length, 2);
 loads[1].resolve('second');
 assert.equal(await retry, 'second');
});

test('different keys load and settle independently', async () => {
 const resolvers = new Map();
 const get = createSingleFlight(key => new Promise(resolve => resolvers.set(key, resolve)));
 const a = get('a');
 const b = get('b');
 assert.notStrictEqual(a, b);
 await Promise.resolve();
 assert.equal(resolvers.size, 2);
 resolvers.get('b')('B');
 assert.equal(await b, 'B');
 assert.strictEqual(get('a'), a);
 resolvers.get('a')('A');
 assert.equal(await a, 'A');
});

test('rejection reaches all waiters and removes the failed entry', async () => {
 const error = new Error('transient');
 let calls = 0;
 let rejectLoad;
 const get = createSingleFlight(() => {
  calls++;
  return calls === 1 ? new Promise((resolve, reject) => { rejectLoad = reject; }) : 'ok';
 });
 const first = get('a');
 const second = get('a');
 assert.strictEqual(first, second);
 const results = Promise.allSettled([first, second]);
 await Promise.resolve();
 assert.equal(calls, 1);
 rejectLoad(error);
 for (const result of await results) {
  assert.equal(result.status, 'rejected');
  assert.strictEqual(result.reason, error);
 }
 const retry = get('a');
 assert.notStrictEqual(retry, first);
 assert.equal(await retry, 'ok');
 assert.equal(calls, 2);
});

test('plain values are wrapped and not cached after fulfillment', async () => {
 let calls = 0;
 const get = createSingleFlight(() => ++calls);
 const first = get('a');
 assert.ok(first instanceof Promise);
 assert.strictEqual(get('a'), first);
 assert.equal(await first, 1);
 assert.equal(await get('a'), 2);
});

test('synchronous throws become shared rejections and permit retry', async () => {
 const error = new Error('synchronous failure');
 let calls = 0;
 const get = createSingleFlight(() => {
  if (++calls === 1) throw error;
  return 'recovered';
 });
 let first;
 assert.doesNotThrow(() => { first = get('a'); });
 assert.ok(first instanceof Promise);
 const second = get('a');
 assert.strictEqual(first, second);
 const results = await Promise.allSettled([first, second]);
 for (const result of results) {
  assert.equal(result.status, 'rejected');
  assert.strictEqual(result.reason, error);
 }
 assert.equal(await get('a'), 'recovered');
 assert.equal(calls, 2);
});

test('handled loader rejection creates no additional unhandled rejection', () => {
 // A separate strict-mode process detects orphaned rejection chains without
 // relying on global unhandledRejection listeners in the test runner.
 const moduleURL = new URL('./singleflight.mjs', import.meta.url).href;
 const result = spawnSync(process.execPath, [
  '--unhandled-rejections=strict', '--input-type=module', '-e',
  `import { createSingleFlight } from ${JSON.stringify(moduleURL)};
   const get = createSingleFlight(() => Promise.reject(new Error('expected')));
   const first = get('a');
   const second = get('a');
   await Promise.all([first.catch(() => {}), second.catch(() => {})]);
   await new Promise(resolve => setImmediate(resolve));`,
 ], { encoding: 'utf8' });
 assert.ifError(result.error);
 assert.equal(result.status, 0, result.stderr);
 assert.equal(result.stderr, '');
});

