import assert from 'node:assert/strict';
import test from 'node:test';
import { createSingleFlight } from './singleflight.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

test('same-key callers share a pending Promise; other keys are independent', async () => {
  const requests = new Map();
  const calls = [];
  const get = createSingleFlight(key => {
    calls.push(key);
    const request = deferred();
    requests.set(key, request);
    return request.promise;
  });

  const a1 = get('a');
  const a2 = get('a');
  const b = get('b');
  assert.ok(a1 instanceof Promise);
  assert.strictEqual(a1, a2);
  assert.notStrictEqual(a1, b);
  await Promise.resolve(); // load runs in the next microtask
  assert.deepEqual(calls, ['a', 'b']);

  requests.get('a').resolve('A');
  requests.get('b').resolve('B');
  assert.deepEqual(await Promise.all([a1, a2, b]), ['A', 'A', 'B']);

  const a3 = get('a');
  assert.notStrictEqual(a3, a1);
  await Promise.resolve();
  assert.deepEqual(calls, ['a', 'b', 'a']);
  requests.get('a').resolve('A again');
  assert.equal(await a3, 'A again');
});

