  const first = deferred();
  let calls = 0;
  const get = createSingleFlight(() => ++calls === 1 ? first.promise : 'recovered');

  const a = get('key');
  const b = get('key');
  assert.strictEqual(a, b);
  await Promise.resolve();
  assert.equal(calls, 1);

  const error = new Error('transient');
  first.reject(error);
  const results = await Promise.allSettled([a, b]);
  assert.deepEqual(results, [
    { status: 'rejected', reason: error },
    { status: 'rejected', reason: error },
  ]);

  assert.equal(await get('key'), 'recovered');
  assert.equal(calls, 2);
});

test('plain values and synchronous throws are returned as Promises; throws can be retried', async () => {
  let calls = 0;
  const error = new Error('synchronous failure');
  const get = createSingleFlight(() => {
    if (++calls === 1) throw error;
    return 42;
  });

  const first = get('key');
  assert.ok(first instanceof Promise);
  await assert.rejects(first, actual => actual === error);

  const second = get('key');
  assert.ok(second instanceof Promise);
  assert.equal(await second, 42);
  assert.equal(calls, 2);

  assert.equal(await get('key'), 42);
  assert.equal(calls, 3);
});

