export function createSingleFlight(load) {
  const pending = new Map();

  return function get(key) {
    if (pending.has(key)) return pending.get(key);

    let promise;
    try {
      promise = Promise.resolve(load(key));
    } catch (error) {
      promise = Promise.reject(error);
    }

    pending.set(key, promise);
    // Handle both outcomes on the side-effect Promise returned by then().
    // Using finally() here would create an unobserved rejected Promise.
    promise.then(
      () => pending.delete(key),
      () => pending.delete(key),
    );
    return promise;
  };
}

