export function createSingleFlight(load) {
 const pending = new Map();
 return function get(key) {
  if (pending.has(key)) return pending.get(key);
  // Defer load into a promise continuation so plain return values and
  // synchronous throws both follow the same Promise-based API.
  const p = Promise.resolve().then(() => load(key));
  pending.set(key,p);
  // Supplying both handlers consumes either settlement on this cleanup
  // chain, avoiding an unhandled rejected promise while leaving p's rejection
  // visible to every caller.
  const cleanup = () => pending.delete(key);
  p.then(cleanup, cleanup);
  return p;
 };
}

