import test from 'node:test';
import assert from 'node:assert/strict';
import { setImmediate as nextTurn } from 'node:timers/promises';
import { createSingleFlight } from './singleflight.mjs';

test('same-key callers share pending promise; fulfilled entries are retried later', async () => {
  let calls = 0;
  let release;
  const get = createSingleFlight(() => {
    calls++;
    if (calls === 1) return new Promise((resolve) => { release = resolve; });
    return 'retried';
  });

  const first = get('same');
  const concurrent = get('same');
  assert.strictEqual(concurrent, first);
  assert.equal(calls, 0); // loader is deferred, but entry is already shared
  await Promise.resolve();
  assert.equal(calls, 1);
  release('loaded');
  assert.deepEqual(await Promise.all([first, concurrent]), ['loaded', 'loaded']);
  assert.equal(await get('same'), 'retried');
  assert.equal(calls, 2);
});

test('different keys load independently', async () => {
  const calls = [];
  const get = createSingleFlight(async (key) => { calls.push(key); return key; });
  const a = get('a');
  const b = get('b');
  assert.notStrictEqual(a, b);
  assert.deepEqual(await Promise.all([a, b]), ['a', 'b']);
  assert.deepEqual(calls.sort(), ['a', 'b']);
});

test('rejection reaches every waiter, cleans up for retry, and adds no unhandled rejection', async () => {
  let calls = 0;
  let rejectLoad;
  const failure = new Error('transient');
  const get = createSingleFlight(() => {
    calls++;
    if (calls === 1) return new Promise((_, reject) => { rejectLoad = reject; });
    return 'recovered';
  });
  const unhandled = [];
  const onUnhandled = (reason) => unhandled.push(reason);
  process.on('unhandledRejection', onUnhandled);
  try {
    const first = get('key');
    const waiter = get('key');
    assert.strictEqual(waiter, first);
    const firstResult = assert.rejects(first, (error) => error === failure);
    const waiterResult = assert.rejects(waiter, (error) => error === failure);
    await Promise.resolve();
    rejectLoad(failure);
    await Promise.all([firstResult, waiterResult]);
    assert.equal(await get('key'), 'recovered');
    assert.equal(calls, 2);
    await nextTurn();
    assert.deepEqual(unhandled, []);
  } finally {
    process.removeListener('unhandledRejection', onUnhandled);
  }
});

test('plain values and synchronous throws always produce promises', async () => {
  const getValue = createSingleFlight(() => 42);
  const valuePromise = getValue('value');
  assert.ok(valuePromise instanceof Promise);
  assert.equal(await valuePromise, 42);

  const failure = new Error('sync failure');
  let calls = 0;
  const getThrow = createSingleFlight(() => {
    calls++;
    if (calls === 1) throw failure;
    return 'retry';
  });
  let result;
  assert.doesNotThrow(() => { result = getThrow('throw'); });
  assert.ok(result instanceof Promise);
  await assert.rejects(result, (error) => error === failure);
  assert.equal(await getThrow('throw'), 'retry');
  assert.equal(calls, 2);
});

