import assert from 'node:assert/strict';
import { createSingleFlight } from './singleflight.mjs';

test('same-key concurrent calls share the pending promise; keys are independent', async () => {
  const resolvers = new Map();
  const calls = [];
  const get = createSingleFlight((key) => {
    calls.push(key);
