    const boom = new Error('boom');
    const get = createSingleFlight(() => { calls++; throw boom; });
    const a = get('k');
    const b = get('k');
    assert.ok(a instanceof Promise);
    assert.equal(a, b);
    const outcomes = await Promise.allSettled([a, b]);
    assert.deepEqual(outcomes.map(({ status, reason }) => status === 'rejected' && reason), [boom, boom]);
    assert.equal(calls, 1);
    // Give Node's unhandled-rejection reporting checkpoint a turn to run.
    await new Promise((resolve) => setImmediate(resolve));
    assert.deepEqual(unhandled, []);
