export function createSingleFlight(load) {
  const pending = new Map();

  return function get(key) {
    if (pending.has(key)) return pending.get(key);

    // Start load in a promise callback so a synchronous throw becomes a
    // rejection and the in-flight entry is installed before load runs.
    const promise = Promise.resolve().then(() => load(key));
    pending.set(key, promise);

    const clear = () => {
      if (pending.get(key) === promise) pending.delete(key);
    };

    // Supplying both handlers makes this cleanup branch always fulfill.  In
    // particular, it does not create a second, unobserved rejected promise.
    void promise.then(clear, clear);

    return promise;
  };
}

