import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import test from 'node:test';

import {createSingleFlight} from './singleflight.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((onResolve, onReject) => {
    resolve = onResolve;
    reject = onReject;
  });
  return {promise, resolve, reject};
}

test('same-key callers share one pending promise and retry after success', async () => {
  const firstLoad = deferred();
  let calls = 0;
  const get = createSingleFlight(() => {
    calls += 1;
    return calls === 1 ? firstLoad.promise : 'second value';
  });

  const first = get('a');
  const shared = get('a');
  assert.strictEqual(shared, first);
  assert.equal(calls, 0, 'load starts asynchronously');

  await Promise.resolve();
  assert.equal(calls, 1);
  firstLoad.resolve('first value');
  assert.equal(await first, 'first value');
  assert.equal(await get('a'), 'second value');
  assert.equal(calls, 2);
});

test('different keys have independent in-flight loads', async () => {
  const loads = new Map();
  const calls = [];
  const get = createSingleFlight((key) => {
    calls.push(key);
    const load = deferred();
    loads.set(key, load);
    return load.promise;
  });

  const a = get('a');
  const b = get('b');
  assert.notStrictEqual(a, b);
  await Promise.resolve();
  assert.deepEqual(calls, ['a', 'b']);

  loads.get('b').resolve('B');
  loads.get('a').resolve('A');
  assert.deepEqual(await Promise.all([a, b]), ['A', 'B']);
});

test('rejection reaches every waiter and a later call retries', async () => {
  const transient = new Error('transient');
  const firstLoad = deferred();
  let calls = 0;
  const get = createSingleFlight(() => {
    calls += 1;
    return calls === 1 ? firstLoad.promise : 'ok';
  });

  const first = get('a');
  const shared = get('a');
  assert.strictEqual(shared, first);
  firstLoad.reject(transient);

  const results = await Promise.allSettled([first, shared]);
  assert.deepEqual(results, [
    {status: 'rejected', reason: transient},
    {status: 'rejected', reason: transient},
  ]);
  assert.equal(await get('a'), 'ok');
  assert.equal(calls, 2);
});

test('plain returns and synchronous throws are always represented by promises', async () => {
  const expected = new Error('synchronous failure');
  let attempts = 0;
  const get = createSingleFlight(() => {
    attempts += 1;
    if (attempts === 1) throw expected;
    return 42;
  });

  let first;
  assert.doesNotThrow(() => {
    first = get('a');
  });
  assert.ok(first instanceof Promise);
  await assert.rejects(first, (error) => error === expected);

  const retry = get('a');
  assert.ok(retry instanceof Promise);
  assert.equal(await retry, 42);
  assert.equal(attempts, 2);
});

test('repro exits cleanly without an additional unhandled rejection', () => {
  const result = spawnSync(process.execPath, ['repro.mjs'], {
    cwd: import.meta.dirname,
    encoding: 'utf8',
  });

  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.signal, null);
  assert.equal(result.stderr, '');
  assert.equal(result.stdout.trim(), 'ok');
});

