export function createSingleFlight(load) {
  const pending = new Map();

  return function get(key) {
    if (pending.has(key)) return pending.get(key);

    // Start the loader in a promise callback so synchronous throws become
    // rejections rather than escaping from get().
    const promise = Promise.resolve().then(() => load(key));
    pending.set(key, promise);

    const remove = () => {
      // Only remove this invocation. This guard keeps cleanup safe if the
      // implementation ever permits a replacement to be installed earlier.
      if (pending.get(key) === promise) pending.delete(key);
    };

    // Supplying both handlers performs cleanup for either outcome and keeps
    // the bookkeeping branch from creating an unhandled rejected promise.
    promise.then(remove, remove);
    return promise;
  };
}

