import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

import { createSingleFlight } from './singleflight.mjs';

test('concurrent calls for one key share the pending promise', async () => {
  let calls = 0;
  let release;
  const gate = new Promise((resolve) => {
    release = resolve;
  });
  const get = createSingleFlight(async (key) => {
    calls += 1;
    await gate;
    return `${key}:${calls}`;
  });

  const first = get('same');
  const second = get('same');

  assert.strictEqual(second, first);
  assert.equal(calls, 0, 'load runs asynchronously so get always returns first');
  await Promise.resolve();
  assert.equal(calls, 1);

  release();
  assert.deepEqual(await Promise.all([first, second]), ['same:1', 'same:1']);
});

test('different keys have independent in-flight requests', async () => {
  const calls = [];
  const get = createSingleFlight(async (key) => {
    calls.push(key);
    return key.toUpperCase();
  });

  const a = get('a');
  const b = get('b');

  assert.notStrictEqual(a, b);
  assert.deepEqual(await Promise.all([a, b]), ['A', 'B']);
  assert.deepEqual(calls, ['a', 'b']);
});

test('a fulfilled request is removed so a later call reloads', async () => {
  let calls = 0;
  const get = createSingleFlight(() => ++calls);

  assert.equal(await get('key'), 1);
  assert.equal(await get('key'), 2);
  assert.equal(calls, 2);
});

test('a rejected request is shared, removed, and retried', async () => {
  let calls = 0;
  const transient = new Error('transient');
  const get = createSingleFlight(async () => {
    calls += 1;
    if (calls === 1) throw transient;
    return 'ok';
  });

  const first = get('key');
  const second = get('key');
  assert.strictEqual(second, first);

  const results = await Promise.allSettled([first, second]);
  assert.deepEqual(
    results.map(({ status, reason }) => ({ status, reason })),
    [
      { status: 'rejected', reason: transient },
      { status: 'rejected', reason: transient },
    ],
  );
  assert.equal(calls, 1);

  assert.equal(await get('key'), 'ok');
  assert.equal(calls, 2);
});

test('plain values and synchronous throws are always exposed as promises', async () => {
  const value = createSingleFlight(() => 42)('value');
  assert.ok(value instanceof Promise);
  assert.equal(await value, 42);

  const failure = new Error('synchronous failure');
  const get = createSingleFlight(() => {
    throw failure;
  });
  let returned;
  assert.doesNotThrow(() => {
    returned = get('failure');
  });
  assert.ok(returned instanceof Promise);
  await assert.rejects(returned, (error) => error === failure);
});

test('rejection cleanup does not create an additional unhandled rejection', async () => {
  const modulePath = fileURLToPath(new URL('./singleflight.mjs', import.meta.url));
  const script = `
    import { pathToFileURL } from 'node:url';
    const { createSingleFlight } = await import(pathToFileURL(process.argv[1]));
    let unhandled = 0;
    process.on('unhandledRejection', () => { unhandled += 1; });
    const error = new Error('expected');
    const get = createSingleFlight(() => Promise.reject(error));
    const first = get('key');
    const second = get('key');
    const settled = await Promise.allSettled([first, second]);
    if (settled.some((item) => item.status !== 'rejected' || item.reason !== error)) {
      process.exitCode = 2;
    }
    await new Promise((resolve) => setImmediate(resolve));
    if (unhandled !== 0) process.exitCode = 3;
  `;

  const child = spawn(process.execPath, ['--input-type=module', '--eval', script, modulePath]);
  let stderr = '';
  child.stderr.setEncoding('utf8');
  child.stderr.on('data', (chunk) => {
    stderr += chunk;
  });
  const [code, signal] = await new Promise((resolve) => {
    child.on('close', (...args) => resolve(args));
  });

  assert.equal(signal, null);
  assert.equal(code, 0, stderr);
});

