import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { reconcile } from './reconcile.mjs';

const set = (id, account, version, amount) => ({ id, account, version, op: 'set', amount });
const del = (id, account, version) => ({ id, account, version, op: 'delete' });
const row = (account, balance, version) => ({ account, balance, version });
const result = (accounts = [], total = 0, duplicates = 0, stale = 0) => ({ accounts, total, duplicates, stale });

test('empty input', () => {
  assert.deepEqual(reconcile([]), result());
});

test('global deduplication precedes account and version selection', () => {
  assert.deepEqual(reconcile([
    set('x', 'a', 1, 2), set('x', 'b', 100, 99), del('x', 'a', 200),
    set('y', 'a', 2, 3), set('x', 'a', 300, 99),
  ]), result([row('a', 3, 2)], 3, 3, 1));
});

test('greatest version wins and all superseded events are stale', () => {
  assert.deepEqual(reconcile([
    set('1', 'a', 1, 10), set('2', 'a', 3, 30),
    set('3', 'a', 2, 20), set('4', 'a', 4, 40),
  ]), result([row('a', 40, 4)], 40, 0, 3));
});

test('equal versions retain first distinct event, including tombstones', () => {
  assert.deepEqual(reconcile([
    set('1', 'a', 3, 10), del('2', 'a', 3), set('3', 'a', 3, 50),
    del('4', 'b', 3), set('5', 'b', 3, 60),
  ]), result([row('a', 10, 3)], 10, 0, 3));
});

test('tombstones defeat older sets; newer sets can reactivate accounts', () => {
  assert.deepEqual(reconcile([
    set('1', 'a', 1, 10), del('2', 'a', 3), set('3', 'a', 2, 20),
    del('4', 'b', 4), set('5', 'b', 2, 20), set('6', 'b', 5, 50),
    del('7', 'c', 6), del('8', 'c', 2),
  ]), result([row('b', 50, 5)], 50, 0, 5));
});

test('a discarded stale event still reserves its ID globally', () => {
  assert.deepEqual(reconcile([
    del('1', 'a', 5), set('x', 'a', 1, 1), set('x', 'b', 9, 99),
  ]), result([], 0, 1, 1));
});

test('ASCII sorting, zero values, safe integer boundary, and special string keys', () => {
  const names = ['z', 'a', '_', 'Z', 'A', '10', '2', '__proto__', 'constructor', ''];
  const events = names.map((name, i) => set(String(i), name, 0, 0));
  events.push(set('max', 'max', Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER));
  const accounts = [...names, 'max'].sort().map(name => row(name,
    name === 'max' ? Number.MAX_SAFE_INTEGER : 0,
    name === 'max' ? Number.MAX_SAFE_INTEGER : 0));
  assert.deepEqual(reconcile(events), result(accounts, Number.MAX_SAFE_INTEGER));
});

test('does not mutate input or reuse input objects as output rows', () => {
  const events = [set('1', 'b', 1, 2), set('2', 'a', 2, 3), del('3', 'b', 0)];
  const original = structuredClone(events);
  events.forEach(Object.freeze);
  Object.freeze(events);
  const output = reconcile(events);
  assert.deepEqual(events, original);
  output.accounts[0].balance = 999;
  assert.deepEqual(events, original);
  assert.deepEqual(reconcile(events), result([row('a', 3, 2), row('b', 2, 1)], 5, 0, 1));
});

test('provided events fixture', () => {
  const events = JSON.parse(readFileSync(new URL('./events.json', import.meta.url), 'utf8'));
  assert.deepEqual(reconcile(events), result([row('b', 40, 3), row('c', 0, 0)], 40, 1, 5));
});

