export function reconcile(events) {
  const seenIds = new Set();
  const winners = new Map();
  let duplicates = 0;

  for (const event of events) {
    // IDs are global, including IDs first encountered on stale events.
    if (seenIds.has(event.id)) {
      duplicates += 1;
      continue;
    }
    seenIds.add(event.id);

    const winner = winners.get(event.account);
    // Keep tombstones and retain the first distinct event on version ties.
    if (winner === undefined || event.version > winner.version) {
      winners.set(event.account, event);
    }
  }

  const accounts = [...winners.values()]
    .filter(event => event.op === 'set')
    .map(event => ({ account: event.account, balance: event.amount, version: event.version }))
    .sort((a, b) => a.account < b.account ? -1 : a.account > b.account ? 1 : 0);

  return {
    accounts,
    total: accounts.reduce((sum, account) => sum + account.balance, 0),
    duplicates,
    // Every account has one final winner, including deleted accounts.
    stale: seenIds.size - winners.size,
  };
}

