    seenIds.add(event.id);
    distinct.push(event);

    const current = winners.get(event.account);
    // Strict greater-than preserves the first distinct event on a version tie.
    if (current === undefined || event.version > current.version) {
      winners.set(event.account, event);
    }
  }

  const accounts = [];
  let stale = 0;
  for (const event of distinct) {
    if (winners.get(event.account) !== event) stale += 1;
  }
  for (const [account, winner] of winners) {
    if (winner.op === 'set') {
      accounts.push({ account, balance: winner.amount, version: winner.version });
    }
  }

  accounts.sort((a, b) => (a.account < b.account ? -1 : a.account > b.account ? 1 : 0));
  const total = accounts.reduce((sum, account) => sum + account.balance, 0);
  return { accounts, total, duplicates, stale };
}

