export function reconcile(events) {
  const seenIds = new Set();
  const uniqueEvents = [];

  // Identity is global: a repeated ID is discarded before account/version
  // reconciliation, regardless of the account on the repeated occurrence.
  for (const event of events) {
    if (seenIds.has(event.id)) continue;
    seenIds.add(event.id);
    uniqueEvents.push(event);
  }

  const winners = new Map();
  for (const event of uniqueEvents) {
    const current = winners.get(event.account);
    // Strictly greater is intentional: ties preserve the first distinct event.
    if (current === undefined || event.version > current.version) {
      winners.set(event.account, event);
    }
  }

  const accounts = [...winners.values()]
    .filter((event) => event.op !== 'delete')
    .map((event) => ({
      account: event.account,
      balance: event.amount,
      version: event.version,
    }))
    .sort((a, b) => (a.account < b.account ? -1 : a.account > b.account ? 1 : 0));

  return {
    accounts,
    total: accounts.reduce((sum, account) => sum + account.balance, 0),
    duplicates: events.length - uniqueEvents.length,
    stale: uniqueEvents.length - winners.size,
  };
}

