      { id: 'd1', account: 'deleted', version: 1, op: 'set', amount: 8 },
      { id: 'd2', account: 'deleted', version: 2, op: 'delete' },
      { id: 'k1', account: 'kept', version: 5, op: 'set', amount: 0 },
      { id: 'k2', account: 'kept', version: 4, op: 'delete' },
    ]),
    {
      accounts: [{ account: 'kept', balance: 0, version: 5 }],
      total: 0,
      duplicates: 0,
      stale: 2,
    },
  );
});

test('sorts active accounts by ASCII order without mutating input', () => {
  const events = [
    { id: 'lower', account: 'a', version: 0, op: 'set', amount: 2 },
    { id: 'upper', account: 'B', version: 0, op: 'set', amount: 1 },
  ];
  const snapshot = structuredClone(events);

  assert.deepEqual(reconcile(events).accounts, [
    { account: 'B', balance: 1, version: 0 },
    { account: 'a', balance: 2, version: 0 },
  ]);
  assert.deepEqual(events, snapshot);
});
